export async function getValidTokens(sessionId: string): Promise<TokenPair> {
  const s = sessions.get(sessionId);
  if (!s) throw new AuthError("ERR_SESSION_NOT_FOUND");
  if (s.tokens.expiresAt > nowSeconds()) return s.tokens;
  // Nhiều request cùng session có thể tới đây cùng lúc -> gọi refresh() song song
  let attempts = 0;
  while (true) {
    try {
      s.tokens = await refresh(s.tokens.refreshToken);
      return s.tokens;
    } catch (err) {
      if (err instanceof AuthError && err.code === "ERR_TOKEN_REUSED" && attempts < 3) {
        attempts++;
        console.log(`[retry] refresh attempt=${attempts} backoff=${attempts * 100}ms`);
        await new Promise((r) => setTimeout(r, attempts * 100));
        // Đọc lại session xem token đã được cập nhật bởi request song song chưa
        const currentS = sessions.get(sessionId);
        if (currentS && currentS.tokens.expiresAt > nowSeconds()) {
          s.tokens = currentS.tokens;
          return s.tokens;
        }
        continue;
      }
      throw err;
    }
  }
}

